package com.ercopac.ercopac_tracker.crm.domain;
import com.ercopac.ercopac_tracker.organisation.domain.Organisation; import jakarta.persistence.*;
@Entity @Table(name="crm_opportunity_equipment") public class CrmOpportunityEquipment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="organisation_id",nullable=false) private Organisation organisation; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="opportunity_id",nullable=false) private CrmOpportunity opportunity; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="equipment_type_id",nullable=false) private CrmEquipmentType equipmentType; @Column(nullable=false) private Integer quantity; public Long getId(){return id;} public Organisation getOrganisation(){return organisation;} public void setOrganisation(Organisation v){organisation=v;} public CrmOpportunity getOpportunity(){return opportunity;} public void setOpportunity(CrmOpportunity v){opportunity=v;} public CrmEquipmentType getEquipmentType(){return equipmentType;} public void setEquipmentType(CrmEquipmentType v){equipmentType=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} }
